      id: "vault-fearless-a-duet-with-john-mayer-fuels-dating-rumors",
      date: "2009-12-11",
      dateLabel: "December 11, 2009",
      title: "A duet with John Mayer fuels dating rumors",
      summary: "A live 'Half of My Heart' at Z100's Jingle Ball, obvious onstage chemistry, a 12-year age gap — and rumors that became a real, brief relationship.",
      body: ["Mayer, then 31, had invited 19-year-old Taylor to sing on \"Half of My Heart\" while he was still finishing Battle Studies, and their live duet at Z100's Jingle Ball made the chemistry public. The romance the rumors predicted did happen — and was over within a couple of months.", "The real aftermath arrived on her next album: \"Dear John\" called out the age gap directly, and Mayer fired back in a 2012 Rolling Stone interview, calling it \"cheap songwriting\" and \"a really lousy thing to do.\""],
      tags: ["Relationship"],
      images: [{ url: "https://i.ytimg.com/vi/U8k_Paf4E14/maxresdefault.jpg", credit: "Still from Samantha Faigen's Dec. 11, 2009 concert footage, via YouTube", caption: "Onstage with John Mayer for the \"Half of My Heart\" duet at Z100's Jingle Ball, Madison Square Garden, Dec. 11, 2009.", kind: "primary", focalPoint: "48% 24%" }],
      sources: [{ name: "Billboard", url: "https://www.billboard.com/music/music-news/john-mayer-taylor-swift-duet-half-of-my-heart-performance-1235291747/" }, { name: "Fox News", url: "https://www.foxnews.com/entertainment/taylor-swift-speak-now-re-release-resurfaces-old-john-mayer-love-story" }, { name: "Just Jared Jr. (photo gallery — Z100 Jingle Ball, Dec. 11, 2009)", url: "https://www.justjaredjr.com/2009/12/12/taylor-swift-jingles-all-the-way/" }],
