      sources: [{ name: "Wikipedia", url: "https://en.wikipedia.org/wiki/Fearless_(Taylor_Swift_album)" }, { name: "Billboard", url: "https://www.billboard.com/music/music-news/taylor-swift-edges-susan-boyle-for-2009s-top-selling-album-2-960801/" }],
