      sources: [{ name: "Children's Mercy kids design wedding gown for Taylor Swift", url: "https://www.kctv5.com/2026/08/03/childrens-mercy-kids-design-wedding-gown-taylor-swift/", reliability: 3, type: "reputable_press" }, { name: "Patients at Children's Mercy Hospital Design a Wedding Gown for Taylor Swift", url: "https://www.yahoo.com/entertainment/celebrity/articles/patients-children-mercy-hospital-design-173148603.html", reliability: 3, type: "reputable_press" }],
