      sources: [{ name: "How Taylor Swift and Travis Kelce's $26 Million Charity Donation is Being Used", url: "https://www.tmz.com/2026/07/02/how-taylor-swift-travis-kelce-charity-donations-are-being-used/", reliability: 3, type: "reputable_press" }, { name: "Taylor Swift, Travis Kelce give $2M to families of fallen NYC first responders", url: "https://www.firerescue1.com/fundraising/taylor-swift-travis-kelce-give-2m-to-families-of-fallen-nyc-first-responders", reliability: 3, type: "reputable_press" }, { name: "Taylor Swift, Travis Kelce Kick Off Wedding Week With $26 Million Charity Donation", url: "https://www.rollingstone.com/music/music-news/taylor-swift-travis-kelce-donate-26-million-charity-1235588245/", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift and Travis Kelce donate $26 million to 20 charities across the country", url: "https://abc7ny.com/post/taylor-swift-travis-kelce-donate-26-million-20-charities-country/19438669/", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift and Travis Kelce Donate $2 Million to NYC First Responder Families Through Answer The Call", url: "https://www.officer.com/features/honoring-the-fallen/news/55393246/taylor-swift-and-travis-kelce-donate-2-million-to-nyc-first-responder-families-through-answer-the-call", reliability: 3, type: "reputable_press" }, { name: "Who We Are — New York Police & Fire Widows' & Children's Benefit Fund", url: "https://www.answerthecall.org/who-we-are/", reliability: 5, type: "official" }],
