      sources: [{ name: "Taylor Swift Styles a Showgirl Orange Reformation Sweater With a Versace Leather Mini Skirt", url: "https://www.marieclaire.com/fashion/celebrity-style/taylor-swift-showgirl-orange-reformation-cashmere-versace-leather-mini-skirt/", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift talks \"luxurious\" album artwork for 'The Life of a Showgirl'", url: "https://www.nme.com/news/music/taylor-swift-talks-luxurious-album-artwork-for-the-life-of-a-showgirl-says-fans-will-see-more-images-than-we-ever-planned-3894073", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift's $70 Orange Cardigan Is the Showgirl Era's First Merch Flex", url: "https://www.marieclaire.com/fashion/celebrity-style/taylor-swift-life-of-a-showgirl-orange-cardigan-merch/", reliability: 4, type: "reputable_press" }, { name: "13 Days Until The Life of a Showgirl", url: "https://www.taylorswiftstyle.com/post-grid/tloas-092025", reliability: 3, type: "blog" }],
      relatedIds: ["moment:vault-tloas-the-showgirl-portraits-mert-and-marcus-rhinestones-and-an-op", "moment:vault-tloas-orange-sequins-and-feathers", "moment:vault-tloas-the-life-of-a-showgirl-arrives-12-tracks-max-martin-and-shel"],
      products: [{ brand: "Reformation", item: "Teo Cashmere Short Sleeve Sweater", retailer: "thereformation.com", url: "https://www.thereformation.com/products/teo-cashmere-short-sleeve-sweater/1313290.html", price: "$64.00", inStock: false, isAlternative: true, altNote: "Her exact \"Cashmere Short Sleeve Crew\" in Showgirl orange is sold out and delisted — this is Reformation's current cashmere short-sleeve crew (the \"Teo\"), same brand and silhouette, also sold out.", imageUrl: "https://media.thereformation.com/image/upload/f_auto,q_auto,dpr_1.0/w_800,c_scale//PRD-SFCC/1313290/CHARCOAL/1313290.1.CHARCOAL?_s=RAABAB0", matchTier: "unscored", kind: "knitwear", verifiedAt: "2026-08-30T19:22:10.691Z" }],
