      images: [{ url: "https://cdn.abcotvs.com/dip/images/19437803_070226-wabc-msg-no-parking-ap-img.jpg", credit: "AP, via ABC7 New York", caption: "The city response the permit paid for: NYPD \"No Parking\" signs going up at the barriers around Madison Square Garden ahead of the wedding weekend.", kind: "primary", focalPoint: "50% 60%" }, { url: "https://www.rollingstone.com/wp-content/uploads/2026/07/Twift-Permit.jpg?w=1600&h=900&crop=1", credit: "Rolling Stone", caption: "Coverage of Taylor Swift's $160,000+ NYC wedding permit payment for her July 3, 2026 Madison Square Garden wedding.", kind: "reference", focalPoint: "50% 35%" }],
      sources: [{ name: "Taylor Swift paid New York City more than $160k for wedding permit, mayor says", url: "https://abcnews.com/GMA/Culture/taylor-swift-paid-new-york-city-160k-wedding/story?id=134655199", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift Paid 'Over $160,000' to Obtain NYC Permit for MSG Wedding, Says Zohran Mamdani", url: "https://www.rollingstone.com/music/music-news/taylor-swift-nyc-permit-cost-msg-wedding-zohran-mamdani-1235592197/", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift Reimbursed NYC for Police Overtime After Wedding, Mayor Confirms", url: "https://www.today.com/popculture/news/taylor-swift-paid-nypd-police-overtime-wedding-zohran-mamdani-rcna385890", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift reportedly paid $160,000 for NYPD cops at Madison Square Garden wedding weekend", url: "https://www.police1.com/taylor-swift-reportedly-paid-160-000-for-nypd-cops-at-madison-square-garden-wedding-weekend", reliability: 3, type: "reputable_press" }, { name: "Taylor Swift and Travis Kelce donate $26 million to charities ahead of wedding", url: "https://www.cbsnews.com/news/taylor-swift-travis-kelce-wedding-donate-charity/", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift and Travis Kelce Made Life-Changing $2M Donation to Families of NYC First Responders", url: "https://entertainmentnow.com/taylor-swift/taylor-swift-travis-kelce-first-responders/", reliability: 3, type: "reputable_press" }],
