      images: [{ url: "https://imagez.tmz.com/image/eb/o/2026/08/16/eb982d6051f24feb90ed3c65dc91a4e1_lg.jpg", credit: "SplashNews.com, via TMZ", caption: "Taylor at Laura Sisk and Oli Jacobs' Aug. 15, 2026 wedding in England, in the navy Costarellos \"Arcangela\" gown.", kind: "primary", focalPoint: "58% 22%" }, { url: "https://imagez.tmz.com/image/33/4by3/2026/08/16/3371a9a6afba4453afb1ec589225192a_md.jpg", credit: "SplashNews.com, via TMZ", caption: "Taylor mid-conversation with wedding guests at Laura Sisk and Oli Jacobs' Aug. 15, 2026 wedding, in the navy Costarellos gown.", kind: "reference", focalPoint: "58% 20%" }],
